    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        params = dict(context.get("params") or {})
        binding_errors = []
        if str(params.get("expected_instruction_sha256") or "") != INSTRUCTION_SHA256:
            binding_errors.append("instruction_sha256")
        if str(params.get("expected_ruleset_sha256") or "") != RULESET_SHA256:
            binding_errors.append("ruleset_sha256")
        if str(params.get("source_simulator_name") or "") != SOURCE_SIMULATOR_NAME:
            binding_errors.append("source_simulator_name")
        if str(params.get("ios_device_profile") or "") != IOS_DEVICE_PROFILE:
            binding_errors.append("ios_device_profile")
        if binding_errors:
            return EvalResult(
                status=EvalStatus.ERROR,
                message="OpenTwitter evaluator binding mismatch: " + ", ".join(binding_errors),
                metadata={
                    "read_only": True,
                    "source_state_mode": "human_completed_eval_only",
                    "ruleset_sha256": RULESET_SHA256,
                    "evaluator_sha256": EVALUATOR_SHA256,
                    "artifact_bindings": ARTIFACT_BINDINGS,
                    "instruction_sha256": INSTRUCTION_SHA256,
                    "binding_errors": binding_errors,
                },
            )

        bundle_id = str(params.get("bundle_id") or DEFAULT_BUNDLE_ID)
        db_path = str(params.get("db_path") or "").strip()
        seed_data_path = str(params.get("seed_data_path") or "").strip()
        data_container_path = str(params.get("data_container_path") or "").strip()
        try:
            if db_path:
                store = OpenTwitterStore(
                    db_path,
                    bundle_id=bundle_id,
                    seed_data_path=seed_data_path or None,
                    data_container_path=data_container_path or None,
                )
            else:
                udid = str(params.get("udid") or "").strip()
                if not udid:
                    return EvalResult(
                        status=EvalStatus.ERROR,
                        message="OpenTwitter evaluator requires the runner-bound simulator UDID",
                        metadata={"read_only": True, "ruleset_sha256": RULESET_SHA256},
                    )
                store = OpenTwitterStore.from_simulator(udid, bundle_id=bundle_id)
            return self.evaluate_state(store.read_state())
        except Exception as exc:
            return EvalResult(
                status=EvalStatus.ERROR,
                message=f"Failed to read OpenTwitter state: {type(exc).__name__}: {exc}",
                metadata={
                    "read_only": True,
                    "source_state_mode": "human_completed_eval_only",
                    "ruleset_sha256": RULESET_SHA256,
                    "evaluator_sha256": EVALUATOR_SHA256,
                    "artifact_bindings": ARTIFACT_BINDINGS,
                    "instruction_sha256": INSTRUCTION_SHA256,
                    "exception_type": type(exc).__name__,
                },
            )
